// Keeps 32-bit ARM (armeabi-v7a) + 64-bit ARM (arm64-v8a) in the shipped APK.
//
// android/app/build.gradle is regenerated by `npx expo prebuild` on every CI
// run, so editing it by hand is not durable. This plugin re-applies the ABI
// config (and the Gradle memory tuning) to the generated files at prebuild
// time. The transformation is idempotent: re-running prebuild never
// duplicates blocks.

const ABI_BLOCK = `
    // --- 32-bit (armeabi-v7a) + 64-bit (arm64-v8a) ARM support -------------
    // Single source of truth: reactNativeArchitectures in gradle.properties.
    def enabledAbis = (findProperty('reactNativeArchitectures') ?: 'armeabi-v7a,arm64-v8a')
            .split(',')*.trim().findAll { it }

    // Off by default: keeps the canonical app-release.apk path intact.
    // ./gradlew assembleRelease -Pandroid.enableAbiSplits=true
    if ((findProperty('android.enableAbiSplits') ?: 'false').toBoolean()) {
        splits {
            abi {
                reset()
                enable true
                universalApk true
                include(*enabledAbis)
            }
        }
    }
`

const NDK_BLOCK = `        // Explicit ABI whitelist: guarantees 32-bit ARM libs are packaged.
        ndk {
            abiFilters(*enabledAbis)
        }
`

const GRADLE_PROPERTIES = {
  "org.gradle.jvmargs": "-Xmx4096m -XX:MaxMetaspaceSize=1024m -XX:+HeapDumpOnOutOfMemoryError -Dfile.encoding=UTF-8",
  "org.gradle.workers.max": "2",
  reactNativeArchitectures: "armeabi-v7a,arm64-v8a",
}

function addAbiConfigToBuildGradle(contents) {
  let result = contents
  if (!result.includes("def enabledAbis")) {
    if (!/android\s*\{\n/.test(result)) {
      throw new Error("Unsupported android/app/build.gradle template (no android { block)")
    }
    result = result.replace(/android\s*\{\n/, `android {\n${ABI_BLOCK}\n`)
  }
  if (!result.includes("abiFilters(")) {
    if (!/\n(\s*)defaultConfig\s*\{\n/.test(result)) {
      throw new Error("Unsupported android/app/build.gradle template (no defaultConfig block)")
    }
    result = result.replace(/\n(\s*)defaultConfig\s*\{\n/, `\n$1defaultConfig {\n${NDK_BLOCK}\n`)
  }
  return result
}

function escapeRegExp(value) {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")
}

function setGradleProperty(contents, key, value) {
  const pattern = new RegExp(`^${escapeRegExp(key)}=.*$`, "m")
  const line = `${key}=${value}`
  return pattern.test(contents)
    ? contents.replace(pattern, line)
    : `${contents.trimEnd()}\n${line}\n`
}

function updateGradleProperties(contents) {
  let result = contents
  for (const [key, value] of Object.entries(GRADLE_PROPERTIES)) {
    result = setGradleProperty(result, key, value)
  }
  return result
}

function withAbiSupport(config) {
  const { withAppBuildGradle, withDangerousMod } = require("@expo/config-plugins")
  const fs = require("fs")
  const path = require("path")

  const withBuildGradle = withAppBuildGradle(config, (config) => {
    config.modResults.contents = addAbiConfigToBuildGradle(config.modResults.contents)
    return config
  })

  return withDangerousMod(withBuildGradle, [
    "android",
    async (config) => {
      const propertiesPath = path.join(config.modRequest.platformProjectRoot, "gradle.properties")
      const current = fs.readFileSync(propertiesPath, "utf8")
      const updated = updateGradleProperties(current)
      if (updated !== current) fs.writeFileSync(propertiesPath, updated)
      return config
    },
  ])
}

module.exports = withAbiSupport
module.exports.addAbiConfigToBuildGradle = addAbiConfigToBuildGradle
module.exports.updateGradleProperties = updateGradleProperties
